code.reference:
def degrade_tier(metrics, rules):
    for index, (metric, op, threshold, tier) in enumerate(rules):
        if metric not in metrics:
            continue
        value = metrics[metric]
        if value >= threshold if op == ">=" else value <= threshold:
            return [tier, index]
    return ["NORMAL", -1]

